query.base:
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
// Split the rule's 24h window into a 3h "recent" slice and a 21h baseline. The recent slice is
// deliberately several times the collection interval so that one missed poll cannot fire the rule.
| EVAL is_recent = @timestamp >= NOW() - 3 hours
// request_count is a ~60s delta counter stored as a gauge. SUM_OVER_TIME totals each series and SUM
// adds the series together: the collector can split one bucket's metric across several series
// (_metric_names_hash is a dimension), and each sample is still counted once. Never RATE() it.
// Totals are kept per clock hour first so that the active baseline hours can be counted below.
| STATS recent         = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_recent,
        baseline       = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE NOT is_recent,
        methods        = VALUES(attributes.method) WHERE NOT is_recent,
        hour_last_seen = MAX(@timestamp)
    BY resource.attributes.bucket_name, resource.attributes.location, hour = TBUCKET(1 hour)
| STATS recent_requests       = SUM(recent),
        baseline_requests     = SUM(baseline),
        baseline_active_hours = COUNT(*) WHERE baseline > 0,
        baseline_methods      = VALUES(methods),
        last_seen             = MAX(hour_last_seen)
    BY resource.attributes.bucket_name, resource.attributes.location
| EVAL recent_requests = COALESCE(recent_requests, 0), baseline_requests = COALESCE(baseline_requests, 0)
// Cast before dividing: request_count is a long and `a / b` would be integer division.
// 21.0 is the baseline slice width in hours — keep it in sync with is_recent/timeWindowSize.
| EVAL baseline_requests_per_hour = ROUND(baseline_requests::DOUBLE / 21.0, 2)

breach.segment:
// "Previously active" means busy AND active through most of the baseline: requiring traffic in at
// least 18 of its 21 hours rules out a bucket used only by a short scheduled batch, which would
// otherwise fire every time the batch finished.
WHERE baseline_requests_per_hour >= 60 AND baseline_active_hours >= 18
// The condition itself. Raise above 0 to catch a severe drop rather than a complete stop.
| WHERE recent_requests == 0
| SORT baseline_requests_per_hour DESC
| LIMIT 50
